import requests
qs=['TITLE:"Single-base-resolution methylomes of populus trichocarpa reveal the association between DNA methylation and drought stress"','"Single-base-resolution methylomes"','AUTH:Schield Populus drought methylation']
for q in qs:
 r=requests.get('https://www.ebi.ac.uk/europepmc/webservices/rest/search',params={'query':q,'format':'json','pageSize':50}).json()
 print('\n',q,'hits',r.get('hitCount'))
 for x in r.get('resultList',{}).get('result',[]): print(x.get('pmid'),x.get('pmcid'),x.get('title'),x.get('authorString'),x.get('journalTitle'),x.get('pubYear'),x.get('doi'))

import requests
url='https://www.ncbi.nlm.nih.gov/research/bionlp/RESTful/pmcoa.cgi/BioC_json/PMC4118614/unicode'
r=requests.get(url); print('STATUS',r.status_code,'LEN',len(r.text))
data=r.json()
for doc in data:
 for p in doc.get('passages',[]):
  sec=p.get('infons',{}).get('section_type','')
